                              >
                                 <span className="text-sm">{category}</span>
                                 <button
                                    type="button"
                                    onClick={() => handleRemoveCategory(category)}
                                    className="ml-1.5 text-gray-500 hover:text-red-400 transition-colors duration-200"
                                 >
                                    <svg
                                       xmlns="http://www.w3.org/2000/svg"
                                       className="h-4 w-4"
