/**
 * Inline editor for the console's single-document pages.
 *
 * The memory page and the skills page both show one Markdown file rendered
 * read-only, with a button that swaps the rendering for a text area. What they
 * share is the part that hurts to get subtly wrong twice: knowing whether the
 * text area still matches what was loaded, carrying the mtime that catches the
 * agent rewriting the file mid-edit, and standing between an unsaved edit and
 * the actions that would throw it away.
 *
 * The workspace preview panel keeps its own copy of this in workspace.js. That
 * one edits whatever text file the panel happens to be showing and drives the
 * panel's own header, so the two have less in common than it first appears.
 */

/**
 * Why the server refused to make a document editable. Truncation is reported
 * first: a partial read can also split a multi-byte character and so come back
 * lossy, but the size is the reason the user needs to hear.
 *
 * @param {object} data - a read response, with `truncated` and `lossy`.
 * @returns {string} an i18n key.
 */
function docUneditableReason(data) {
    if (data.truncated) return 'ws_edit_too_large';
    if (data.lossy) return 'ws_edit_encoding';
    return 'ws_edit_unsupported';
}

/**
 * Build an editor bound to one page's DOM and API.
 *
 * @param {object} cfg
 * @param {function(): HTMLElement} cfg.body - element the document is drawn
 *   into, and which the text area takes over while editing.
 * @param {function(): object} cfg.buttons - `{edit, save, cancel}` elements to
 *   show and hide; any of them may be absent.
 * @param {function(object): Promise<object>} cfg.read - fetch the document's
 *   current text. Resolves with the API payload: `content`, `mtime`,
 *   `editable`, plus `truncated` / `lossy` to explain a refusal.
 * @param {function(object, string, ?number): Promise<object>} cfg.write - save
 *   `content` against an expected mtime, resolving with the raw response so a
 *   `conflict` code can be put to the user here.
 * @param {function(object): void} cfg.render - redraw the read-only view from
 *   the document's `content`.
 * @param {function(object): boolean} [cfg.canEdit] - whether this document may
 *   be edited at all. A false answer hides the edit button rather than letting
 *   the click fail; used for skills that ship with the installation.
 * @param {function(object): string} [cfg.refusal] - i18n key explaining a read
 *   response whose `editable` is false, when the page knows a better reason
 *   than the generic ones. Defaults to {@link docUneditableReason}.
 * @param {function(object): void} [cfg.onState] - called with
 *   `{editing, dirty}` whenever either changes, for a title marker or similar.
 */
function createDocEditor(cfg) {
    // The document on screen: whatever shape the host page uses, plus the
    // `content` field this editor keeps current as it loads and saves.
    let doc = null;
    let editing = false;
    let baseline = '';
    let baseMtime = null;
    let saving = false;

    function textarea() {
        return cfg.body()?.querySelector('textarea.doc-editor') || null;
    }

    function isDirty() {
        const ta = textarea();
        return editing && !!ta && ta.value !== baseline;
    }

    function sync() {
        const { edit, save: saveBtn, cancel: cancelBtn } = cfg.buttons() || {};
        const canEdit = !!doc && (!cfg.canEdit || cfg.canEdit(doc));
        edit?.classList.toggle('hidden', !canEdit || editing);
        saveBtn?.classList.toggle('hidden', !editing);
        cancelBtn?.classList.toggle('hidden', !editing);
        cfg.onState?.({ editing: editing, dirty: isDirty() });
    }

    /** Adopt a freshly opened document and draw it read-only. */
    function open(next) {
        doc = next;
        editing = false;
        baseline = '';
        baseMtime = null;
        cfg.render(doc);
        sync();
    }

    /** Drop all state without touching what is on screen. */
    function forget() {
        doc = null;
        editing = false;
        baseline = '';
        baseMtime = null;
        sync();
    }

    /**
     * Gate an action that would throw away the text area's contents.
     *
     * @param {function} next - runs once the user agrees to lose the edits, and
     *   owns whatever replaces the editor. It runs with edit mode already off,
     *   so it must not be a function that bails out when not editing.
     * @returns {boolean} true when there is nothing to lose and the caller may
     *   go ahead; false once the confirmation is on screen.
     */
    function guard(next) {
        if (!isDirty()) return true;
        showConfirmDialog({
            title: t('ws_edit_discard_title'),
            message: t('ws_edit_discard_msg'),
            okText: t('ws_edit_discard_ok'),
            onConfirm: () => {
                editing = false;
                next();
            },
        });
        return false;
    }

    /** Load the document's current text into a text area. */
    async function start() {
        if (editing || !doc) return;
        const target = doc;
        const body = cfg.body();
        if (!body) return;
        body.innerHTML = '<div class="py-10 text-center text-slate-400 dark:text-slate-500">'
            + '<i class="fas fa-spinner fa-spin"></i></div>';

        let data;
        try {
            data = await cfg.read(target);
        } catch (e) {
            _wsToast(`${t('ws_edit_load_failed')}: ${e.message}`);
            cfg.render(target);
            return;
        }
        // The user may have navigated away while the request was in flight.
        if (doc !== target) return;
        if (!data.editable) {
            _wsToast(t((cfg.refusal || docUneditableReason)(data)));
            cfg.render(target);
            return;
        }

        // Adopt the text just read: the agent may have rewritten the file since
        // the page rendered it, and leaving on save would otherwise redraw the
        // stale copy.
        target.content = data.content;
        editing = true;
        baseMtime = data.mtime;
        // Read the baseline back out of the text area rather than using the
        // response text: a text area normalizes CRLF to LF in its value, so a
        // CRLF file would compare as modified from the moment it loaded.
        baseline = mount(body, data.content).value;
        sync();
    }

    /** @returns {HTMLTextAreaElement} the text area now holding the document. */
    function mount(body, content) {
        body.innerHTML = '';
        const ta = document.createElement('textarea');
        ta.className = 'doc-editor';
        ta.spellcheck = false;
        ta.value = content;
        body.appendChild(ta);

        ta.addEventListener('input', sync);
        ta.addEventListener('keydown', (e) => {
            if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') {
                // Save in place, the way an editor does. The Save button
                // instead returns to the rendered document.
                e.preventDefault();
                save({ keepEditing: true });
            } else if (e.key === 'Escape') {
                e.preventDefault();
                cancel();
            } else if (e.key === 'Tab') {
                // Otherwise Tab leaves the text area, which is never what
                // indenting a line is meant to do.
                e.preventDefault();
                const { selectionStart: from, selectionEnd: to } = ta;
                ta.value = `${ta.value.slice(0, from)}    ${ta.value.slice(to)}`;
                ta.selectionStart = ta.selectionEnd = from + 4;
                sync();
            }
        });
        ta.focus();
        return ta;
    }

    /**
     * Write the text area back to disk.
     *
     * @param {object} [opts]
     * @param {boolean} [opts.keepEditing] - stay in the editor after saving.
     * @param {boolean} [opts.force] - save even though the file changed on disk.
     */
    async function save(opts) {
        const { keepEditing = false, force = false } = opts || {};
        const ta = textarea();
        if (!editing || !doc || !ta) return;
        // Ctrl+S bypasses the button's busy state, and a second save sent
        // before the first reply carries a stale mtime - which would come back
        // as a conflict against our own write.
        if (saving) return;
        // Writing an untouched file would bump its mtime for nothing.
        if (!force && !isDirty()) {
            if (!keepEditing) exit();
            return;
        }

        const target = doc;
        const content = ta.value;
        const btn = cfg.buttons()?.save;
        saving = true;
        btn?.classList.add('doc-btn-busy');
        try {
            const data = await cfg.write(target, content, force ? null : baseMtime);
            if (data.code === 'conflict') {
                showConfirmDialog({
                    title: t('ws_edit_conflict_title'),
                    message: t('ws_edit_conflict_msg'),
                    okText: t('ws_edit_overwrite'),
                    onConfirm: () => save({ keepEditing: keepEditing, force: true }),
                });
                return;
            }
            if (data.status !== 'success') throw new Error(data.message || 'save failed');

            baseline = content;
            baseMtime = data.mtime;
            target.content = content;
            _wsToast(t('ws_edit_saved'));
            if (keepEditing) sync();
            else exit();
        } catch (e) {
            _wsToast(`${t('ws_edit_save_failed')}: ${e.message}`);
        } finally {
            saving = false;
            btn?.classList.remove('doc-btn-busy');
        }
    }

    function cancel() {
        if (!editing) return;
        // Retry through exit() rather than through this function, which bails
        // out on the very flag the guard clears before retrying.
        if (!guard(exit)) return;
        exit();
    }

    /** Leave the editor and show the rendered document again. */
    function exit() {
        editing = false;
        baseline = '';
        baseMtime = null;
        if (doc) cfg.render(doc);
        sync();
    }

    return {
        open: open,
        forget: forget,
        start: start,
        save: save,
        cancel: cancel,
        exit: exit,
        guard: guard,
        isDirty: isDirty,
        isEditing: () => editing,
        current: () => doc,
    };
}

import React, { useEffect, useLayoutEffect } from 'react'
import { AlertTriangle, Loader2, Pencil, RotateCcw, Save, X } from 'lucide-react'
import type { LucideIcon } from 'lucide-react'
import { t } from '../i18n'
import { useConfirmStore } from '../store/confirmStore'
import type { DocEditorStore } from '../store/docEditorStore'

/**
 * Text area for a document page's editor, and the header buttons that drive it.
 *
 * The counterpart of the preview panel's FileEditor, for the pages that show one
 * document at a time (memory files, skill definitions) rather than a file tree.
 */
export function DocEditor<D>({
  store,
  textareaRef: ref,
}: {
  store: DocEditorStore<D>
  /** Owned by the page so its Save button can read the current text. */
  textareaRef: React.RefObject<HTMLTextAreaElement>
}): React.ReactElement | null {
  const edit = store((s) => s.edit)
  const setDirty = store((s) => s.setDirty)
  const stashText = store((s) => s.stashText)
  const save = store((s) => s.save)
  const cancelEdit = store((s) => s.cancelEdit)
  const pendingConfirm = useConfirmStore((s) => s.pending)

  const baseline = edit?.baseline

  // autoFocus covers the normal mount. This also hands focus back once a dialog
  // that took it (discard / overwrite) has closed, so typing resumes without a
  // click. Keyed on the dialog rather than running every render, which would
  // fight the user for focus on the header buttons.
  useLayoutEffect(() => {
    const el = ref.current
    if (!pendingConfirm && el && document.activeElement !== el) el.focus()
  }, [pendingConfirm])

  // Leaving the page unmounts the text area; hand the work in progress back to
  // the store so returning restores it rather than losing it.
  useEffect(() => {
    const el = ref.current
    return () => {
      if (el) stashText(el.value)
    }
  }, [])

  // A save in place moves the baseline. Re-derive from the text area rather than
  // trusting the store's `dirty: false`, in case the user kept typing while the
  // write was in flight.
  useEffect(() => {
    if (ref.current && baseline !== undefined) setDirty(ref.current.value !== baseline)
  }, [baseline])

  if (!edit) return null

  const onChange = () => setDirty((ref.current?.value ?? '') !== edit.baseline)

  const onKeyDown = (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
    if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 's') {
      // Save in place, the way an editor does. The Save button in the header
      // instead returns to the rendered document.
      e.preventDefault()
      void save(e.currentTarget.value, { keepEditing: true })
      return
    }
    if (e.key === 'Escape') {
      e.preventDefault()
      void cancelEdit()
      return
    }
    if (e.key === 'Tab') {
      // Otherwise Tab moves focus out of the text area, which is never what
      // indenting a line is meant to do.
      e.preventDefault()
      const el = e.currentTarget
      const { selectionStart: start, selectionEnd: end } = el
      el.value = `${el.value.slice(0, start)}    ${el.value.slice(end)}`
      el.selectionStart = el.selectionEnd = start + 4
      onChange()
    }
  }

  return (
    <div className="h-full flex flex-col">
      {edit.error && (
        <div className="shrink-0 flex items-start gap-1.5 px-4 py-2 text-[12px] text-red-500 bg-red-500/10 border-b border-default">
          <AlertTriangle size={13} className="mt-0.5 shrink-0" />
          <span className="break-all">{edit.error}</span>
        </div>
      )}
      <textarea
        ref={ref}
        // Uncontrolled: React seeds the node and then leaves the text alone, so
        // typing never round-trips through a re-render.
        defaultValue={edit.loaded}
        autoFocus
        onChange={onChange}
        onKeyDown={onKeyDown}
        spellCheck={false}
        // Wrapped rather than scrolling sideways: these are prose documents, and
        // a horizontal scrollbar hides the end of every long paragraph.
        className="flex-1 min-h-0 w-full p-4 bg-transparent text-content font-mono text-[12.5px] leading-relaxed border-0 outline-none resize-none whitespace-pre-wrap overflow-x-hidden overflow-y-auto"
        // `anywhere` covers the unbreakable cases (a long URL) that wrapping on
        // its own would still push off the right edge.
        style={{ tabSize: 4, overflowWrap: 'anywhere' }}
      />
    </div>
  )
}

/**
 * Edit / Save / Discard for a document page's header.
 *
 * Which buttons appear is derived from the store, so a page only has to place
 * this once and the two modes stay in step.
 */
export function DocActions<D>({
  store,
  textareaRef: ref,
}: {
  store: DocEditorStore<D>
  textareaRef: React.RefObject<HTMLTextAreaElement>
}): React.ReactElement | null {
  const doc = store((s) => s.doc)
  const edit = store((s) => s.edit)
  const readonly = store((s) => s.readonly)
  const loading = store((s) => s.loading)
  const startEdit = store((s) => s.startEdit)
  const save = store((s) => s.save)
  const cancelEdit = store((s) => s.cancelEdit)

  if (!doc) return null

  if (!edit) {
    if (readonly || loading) return null
    return (
      // The long form carries the keyboard hints, which don't fit on the button.
      <DocBtn onClick={() => void startEdit()} icon={Pencil} title={t('ws_edit')}>
        {t('doc_edit')}
      </DocBtn>
    )
  }

  return (
    <>
      <DocBtn
        primary
        busy={edit.saving}
        // Never fall back to '' for a missing text area: that would write an
        // empty file over the user's content.
        onClick={() => {
          const el = ref.current
          if (el) void save(el.value)
        }}
        icon={edit.saving ? Loader2 : Save}
      >
        {t('doc_edit_save')}
      </DocBtn>
      <DocBtn onClick={() => void cancelEdit()} icon={RotateCcw}>
        {t('ws_edit_cancel')}
      </DocBtn>
    </>
  )
}

const DocBtn: React.FC<{
  onClick: () => void
  icon: LucideIcon
  primary?: boolean
  busy?: boolean
  title?: string
  children: React.ReactNode
}> = ({ onClick, icon: Icon, primary, busy, title, children }) => (
  <button
    onClick={onClick}
    disabled={busy}
    title={title}
    className={`inline-flex items-center gap-1.5 px-3 py-1.5 rounded-btn text-sm transition-colors cursor-pointer disabled:opacity-50 disabled:cursor-default ${
      primary
        ? 'bg-accent text-white hover:opacity-90'
        : 'text-content-secondary hover:bg-inset border border-strong'
    }`}
  >
    <Icon size={14} className={busy ? 'animate-spin' : undefined} />
    {children}
  </button>
)

/** The reason an edit was refused, or a read that failed. */
export function DocNotice<D>({ store }: { store: DocEditorStore<D> }): React.ReactElement | null {
  const notice = store((s) => s.notice)
  const dismissNotice = store((s) => s.dismissNotice)

  if (!notice) return null

  return (
    <div className="shrink-0 flex items-start gap-1.5 px-6 py-2 text-[12px] text-amber-600 bg-amber-500/10 border-b border-default">
      <AlertTriangle size={13} className="mt-0.5 shrink-0" />
      <span className="flex-1 break-all">{notice}</span>
      <button onClick={dismissNotice} title={t('ws_close')} className="shrink-0 opacity-60 hover:opacity-100 cursor-pointer">
        <X size={13} />
      </button>
    </div>
  )
}

import React, { createContext, useContext, useState, useMemo } from 'react';

/**
 * Mutation state context - for components that need to know about save/edit status
 * Separated from code state to prevent unnecessary re-renders
 */
interface MutationContextType {
  isMutating: boolean;
  setIsMutating: React.Dispatch<React.SetStateAction<boolean>>;
}

/**
 * Code state context - for components that need the current code content
 * Changes frequently (on every keystroke), so only subscribe if needed
 */
interface CodeContextType {
  currentCode?: string;
  setCurrentCode: React.Dispatch<React.SetStateAction<string | undefined>>;
}

const MutationContext = createContext<MutationContextType | undefined>(undefined);
const CodeContext = createContext<CodeContextType | undefined>(undefined);

/**
 * Provides editor state management for artifact code editing
 * Split into two contexts to prevent unnecessary re-renders:
 * - MutationContext: for save/edit status (changes rarely)
 * - CodeContext: for code content (changes on every keystroke)
 */
export function EditorProvider({ children }: { children: React.ReactNode }) {
  const [isMutating, setIsMutating] = useState(false);
  const [currentCode, setCurrentCode] = useState<string | undefined>();

  const mutationValue = useMemo(() => ({ isMutating, setIsMutating }), [isMutating]);
  const codeValue = useMemo(() => ({ currentCode, setCurrentCode }), [currentCode]);

  return (
    <MutationContext.Provider value={mutationValue}>
      <CodeContext.Provider value={codeValue}>{children}</CodeContext.Provider>
    </MutationContext.Provider>
  );
}

/**
 * Hook to access mutation state only
 * Use this when you only need to know about save/edit status
 */
export function useMutationState() {
  const context = useContext(MutationContext);
  if (context === undefined) {
    throw new Error('useMutationState must be used within an EditorProvider');
  }
  return context;
}

/**
 * Hook to access code state only
 * Use this when you need the current code content
 */
export function useCodeState() {
  const context = useContext(CodeContext);
  if (context === undefined) {
    throw new Error('useCodeState must be used within an EditorProvider');
  }
  return context;
}

/**
 * @deprecated Use useMutationState() and/or useCodeState() instead
 * This hook causes components to re-render on every keystroke
 */
export function useEditorContext() {
  const mutation = useMutationState();
  const code = useCodeState();
  return { ...mutation, ...code };
}

